mapper.select:
SELECT 
FROM yglue_project_code_snapshot
WHERE project_id = #{projectId}
  AND snapshot_key = #{snapshotKey}

mapper.delete:
DELETE FROM yglue_project_snapshot_dependency WHERE snapshot_id = #{snapshotId};
DELETE FROM yglue_project_snapshot_class_method
WHERE class_id IN (
    SELECT id FROM yglue_project_snapshot_class WHERE snapshot_id = #{snapshotId}
);
DELETE FROM yglue_project_snapshot_class_field
WHERE class_id IN (
    SELECT id FROM yglue_project_snapshot_class WHERE snapshot_id = #{snapshotId}
);
DELETE FROM yglue_project_snapshot_class WHERE snapshot_id = #{snapshotId};
